insert into public.catalog_release_items(release_id,library_id,object_type,object_id,version_id,content_hash,sort_order)values('a2130000-0000-4000-8000-000000000102','a2130000-0000-4000-8000-000000000100','SUBCATEGORY','a2130000-0000-4000-8000-000000000105','a2130000-0000-4000-8000-000000000106',repeat('a',64),3);
