insert into public.questionnaire_versions(id,questionnaire_id,library_id,catalog_release_id,version,status,title_fr,title_ar,description_fr,description_ar,audience,engine_version,policy_version,snapshot_hash,translation_review_status,translation_reviewer_user_id,translation_reviewed_at,translation_review_proof_hash,translation_review_version,change_reason,created_by)values('a2130000-0000-4000-8000-000000000201','a2130000-0000-4000-8000-000000000200','a2130000-0000-4000-8000-000000000100','a2130000-0000-4000-8000-000000000102',1,'DRAFT','Diagnostic canonique213','تشخيص قانوني213','Référence pour recette des règles publiées','مرجع اختبار القواعد المنشورة','CLIENT','2.0.0','CANONICAL213_V1',repeat('b',64),'APPROVED','a2130000-0000-4000-8000-000000000002',now(),repeat('b',64),1,'Précondition historique de recette','a2130000-0000-4000-8000-000000000001');
update public.questionnaire_versions set status='PUBLISHED',published_at=clock_timestamp()where id='a2130000-0000-4000-8000-000000000201';
update public.questionnaires set status='PUBLISHED',current_published_version_id='a2130000-0000-4000-8000-000000000201'where id='a2130000-0000-4000-8000-000000000200';
set local session_replication_role=origin;
insert into public.organization_memberships(id,organization_id,user_id,status)values('a2130000-0000-4000-8000-000000000012','a2130000-0000-4000-8000-000000000010','a2130000-0000-4000-8000-000000000002','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('a2130000-0000-4000-8000-000000000012','CLIENT_ADMIN');
insert into public.platform_user_roles(user_id,role_code)values('a2130000-0000-4000-8000-000000000001','FINANCE_MANAGER'),('a2130000-0000-4000-8000-000000000002','FINANCE_MANAGER');
insert into public.tax_categories(code,name_fr,name_ar,description_fr,description_ar,category_kind,status)values('CLIENT_TAX213_TEST','Fiscalité de recette213','ضريبة اختبار213','Référence strictement synthétique et transactionnelle','مرجع اصطناعي للمعاملة فقط','SERVICE','ACTIVE');
select set_config('test.tax213_payload',jsonb_build_object('description','Description complète de la demande de recette fiscale','urgency','NORMAL','currency_code','MAD','required_quote_data',jsonb_build_object('region_code','CASABLANCA_SETTAT','service_version_id','a2130000-0000-4000-8000-000000009999','country_code','US','tax_effective_on','2000-01-01','tax_category_code','FORGED_EXEMPT','tax_category_policy_snapshot',jsonb_build_object('approval_reference','FORGED')),'required_fields_complete',true,'catalog_snapshot_hash',repeat('a',64),'questionnaire_snapshot_hash',repeat('b',64))::text,true);
select set_config('request.jwt.claims','{"sub":"a2130000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select set_config('test.tax213_request',public.create_service_request('a2130000-0000-4000-8000-000000000010','a2130000-0000-4000-8000-000000000100','a2130000-0000-4000-8000-000000000107','a2130000-0000-4000-8000-000000000201',current_setting('test.tax213_payload')::jsonb,'Création de recette avec fiscalité manquante','tax213-create')::text,true);
select is(current_setting('test.tax213_request')::jsonb->>'status','DRAFT','a real DRAFT can be created without a mapping');
select throws_ok($$select public.mark_service_request_ready((current_setting('test.tax213_request')::jsonb->>'request_id')::uuid,1,'Informations confirmées','tax213-ready-missing')$$,'55000','SERVICE_TAX_CATEGORY_POLICY_REQUIRED','READY fails closed without approved mapping');
select throws_ok($$select public.mark_service_request_ready((current_setting('test.tax213_request')::jsonb->>'request_id')::uuid,null,'Informations confirmées','tax213-ready-null')$$,'40001','STALE_REQUEST_VERSION','NULL cannot bypass request CAS');
reset role;
select is((select count(*)::integer from public.service_request_tax_origins_v1 where request_id=(current_setting('test.tax213_request')::jsonb->>'request_id')::uuid),1,'one immutable fiscal origin is preserved even before mapping');
select is((select country_code from public.service_request_tax_origins_v1 where request_id=(current_setting('test.tax213_request')::jsonb->>'request_id')::uuid),'MA','country is canonical rather than caller US');
select is((select tax_effective_on from public.service_request_tax_origins_v1 where request_id=(current_setting('test.tax213_request')::jsonb->>'request_id')::uuid),(clock_timestamp()at time zone'Africa/Casablanca')::date,'fiscal date is server request date rather than caller 2000');
select is((select service_version_id from public.service_request_tax_origins_v1 where request_id=(current_setting('test.tax213_request')::jsonb->>'request_id')::uuid),'a2130000-0000-4000-8000-000000000108'::uuid,'source is the unique exact published service version');
select ok(not exists(select 1 from public.service_request_versions where id=(current_setting('test.tax213_request')::jsonb->>'request_version_id')::uuid and(required_quote_data?'tax_category_code'or required_quote_data?'tax_category_policy_snapshot')),'caller category and fake approval are stripped');
select is((select row_version from public.service_requests where id=(current_setting('test.tax213_request')::jsonb->>'request_id')::uuid),1,'refused READY leaves request CAS unchanged');
-- The tax rule and mapping are created and independently reviewed by their real
-- commands; this synthetic TEST policy exists only inside this rolled-back test.
set local role authenticated;
select set_config('test.tax213_rule',public.propose_morocco_tax_rule('a2130000-0000-4000-8000-000000000010','CLIENT_TAX213_TEST','VAT',2000,100,'{}','TEST-ONLY transactional fiscal rule213',current_date-1,current_date+365,'Recette locale du raccord fiscal213','tax213-rule-proposal')::text,true);
select set_config('request.jwt.claims','{"sub":"a2130000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.decide_morocco_tax_rule('a2130000-0000-4000-8000-000000000010',(current_setting('test.tax213_rule')::jsonb->>'tax_rule_version_id')::uuid,'APPROVE','VALIDATED','TEST-ONLY-TAX213','Validation synthétique transactionnelle213',1,'tax213-rule-decision')$$,'independent reviewer activates the synthetic dated rule');
reset role;
select set_config('test.tax213_scope',private.service_tax_mapping_scope_hash_v1('DEVELOPMENT','a2130000-0000-4000-8000-000000000108','MA','MAD'),true);
select set_config('request.jwt.claims','{"sub":"a2130000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select set_config('test.tax213_mapping',public.propose_service_tax_category_mapping_v1('a2130000-0000-4000-8000-000000000108',repeat('a',64),current_setting('test.tax213_scope'),'MA','MAD','CLIENT_TAX213_TEST',current_date,current_date+365,true,array[]::uuid[],'Association synthétique de recette213','a2130000-0000-4000-8000-000000000301')::text,true);
select set_config('request.jwt.claims','{"sub":"a2130000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.decide_service_tax_category_mapping_v1((current_setting('test.tax213_mapping')::jsonb->>'proposal_id')::uuid,current_setting('test.tax213_mapping')::jsonb->>'content_hash',true,'TEST-ONLY-MAPPING213','Association revue indépendamment pour la recette')$$,'independent finance reviewer publishes the real mapping command');
select set_config('request.jwt.claims','{"sub":"a2130000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select set_config('test.tax213_ready',public.mark_service_request_ready((current_setting('test.tax213_request')::jsonb->>'request_id')::uuid,1,'Informations confirmées','tax213-ready')::text,true);
select is(current_setting('test.tax213_ready')::jsonb->>'outcome','SERVICE_REQUEST_READY','same real draft becomes READY after mapping approval');
select is(current_setting('test.tax213_ready')::jsonb->>'row_version','2','one READY transition increments CAS once');
select is(public.mark_service_request_ready((current_setting('test.tax213_request')::jsonb->>'request_id')::uuid,1,'Informations confirmées','tax213-ready'),current_setting('test.tax213_ready')::jsonb,'READY replay returns exactly the same immutable version');
select set_config('request.jwt.claims','{"sub":"a2130000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.mark_service_request_ready((current_setting('test.tax213_request')::jsonb->>'request_id')::uuid,1,'Informations confirmées','tax213-ready')$$,'42501','REQUEST_SCOPE_DENIED','foreign actor cannot replay READY');
reset role;
select is((select count(*)::integer from public.service_request_versions where request_id=(current_setting('test.tax213_request')::jsonb->>'request_id')::uuid),2,'approved fiscal snapshot appends one version without rewriting the old version');
select is((select required_quote_data->>'tax_category_code'from public.service_request_versions where id=(current_setting('test.tax213_ready')::jsonb->>'request_version_id')::uuid),'CLIENT_TAX213_TEST','READY version contains server approved category');
select is((select required_quote_data#>>'{tax_category_policy_snapshot,mapping_id}'from public.service_request_versions where id=(current_setting('test.tax213_ready')::jsonb->>'request_version_id')::uuid),current_setting('test.tax213_mapping')::jsonb->>'proposal_id','READY snapshot pins the exact reviewed mapping');
select is((select count(*)::integer from public.audit_events where resource_id=current_setting('test.tax213_request')::jsonb->>'request_id'and action='rfq.request.ready'),1,'one audited READY fact despite replay');
select throws_ok($$update public.service_request_tax_origins_v1 set country_code='US'where request_id=(current_setting('test.tax213_request')::jsonb->>'request_id')::uuid$$,'55000','IMMUTABLE_RECORD','fiscal origin cannot be rewritten');
select ok(not has_table_privilege('authenticated','public.service_request_tax_origins_v1','SELECT')and not has_function_privilege('authenticated','private.client_request_tax_quote_data_v1(uuid,text,char(3),jsonb,boolean,boolean)','EXECUTE'),'origins and deriving helper have no direct API bypass');
select*from finish();
rollback;
